/**
 * 这个 helper 以前把 `kind: '学术综述'` 和 `checked: true` 一起写死，于是每加
 * 一条来源就自动获得一枚「已核验」印章。本轮审查在这批来源里查出 404 链接、
 * 凭空写出的章节号，以及一份被标成「学术综述」的原典全文，正是这么来的。
 *
 * 现在核验状态和文献性质都必须显式传入：没有本轮实际打开核对过的来源只能是
 * 'pending'；古登堡、维基文库上的原文入口必须传 kind: '原典'。
 */
const source = (
  id: string,
  title: string,
  url: string,
  locator: string,
  supports: string,
  checked: SourceCheckState = 'pending',
  checkedOn?: string,
  kind: LedgerSource['kind'] = '学术综述',
): LedgerSource => ({ id, title, kind, url, locator, checked, checkedOn, supports });

